@media (prefers-color-scheme: light) {
  color-scheme: light;
  ::selection {
    background-color: rgba(136, 57, 239, 0.3);
  }
  input::placeholder,
  textarea::placeholder {
    color: #6c6f85 !important;
  }
  html,
  html body {
    color: #4c4f69;
    background-color: #eff1f5;
  }
  /* Components */
  a,
  .mimic-link {
    color: #8839ef;
  }
  .btn-primary {
    background-color: #8839ef;
    color: #dce0e8;
  }
  .btn-primary:hover {
    background-color: #7a21ed !important;
    color: #dce0e8 !important;
  }
  .btn-secondary {
    background-color: #ccd0da;
    color: #4c4f69;
  }
  .btn-secondary:hover {
    background-color: #bcc0cc !important;
    color: #4c4f69 !important;
  }
  .btn-cancel {
    color: #5c5f77;
  }
  .dropdown-menu-clickable {
    background: #e6e9ef;
  }
  .dropdown-menu-clickable::before {
    filter: brightness(0) saturate(100%) invert(89%) sepia(26%) saturate(508%) hue-rotate(188deg) brightness(107%) contrast(90%);
  }
  .dropdown-menu-clickable .dropdown-menu-clickable-item {
    color: #4c4f69;
  }
  .dropdown-menu-clickable .dropdown-menu-clickable-item:hover {
    background-color: #eff1f5 !important;
  }
  .dropdown-menu-clickable .dropdown-menu-clickable-item.dropdown-menu-clickable-item--selected {
    color: #8839ef;
  }
  .dropdown-menu-clickable-button {
    color: #6c6f85;
  }
  .dropdown-menu-clickable-button:hover,
  .dropdown-menu-clickable-button.disclose-active {
    color: #5c5f77;
  }
  .section-with-settings .dropdown-menu-clickable-button.section-control::before {
    border-right-color: #acb0be;
  }
  .dropdown-menu-clickable-button::after {
    filter: brightness(0) saturate(100%) invert(63%) sepia(28%) saturate(515%) hue-rotate(196deg) brightness(48%) contrast(67%);
  }
  .content-form textarea,
  .content-form input,
  .content-form select {
    background-color: #e6e9ef !important;
    color: #4c4f69 !important;
    border-color: #bcc0cc !important;
  }
  .content-form textarea:focus,
  .content-form input:focus,
  .content-form select:focus {
    box-shadow: 0 3px 9px 0 #ccd0da !important;
  }
  .content-form .lfm-form-radio input[type="radio"] + label::before {
    background-color: #eff1f5;
